# CELL 16: LOOK AT ONE STRUCTURE   (Eir 2.0.13)
# ============================================================================
# Put an ICSD code in and get everything Eir knows about that entry: the
# verdict and the measurement behind it, every site, and - if you ask for it
# - the coordination polyhedron in 3D.
#
# This sits at the END of the reporting on purpose. The summary, the triage
# and the figures tell you WHICH structures to look at; this is where you
# then look. Re-run it as often as you like: it draws at most a handful of
# viewers and resets its own counter each call, so it cannot do what the
# automatic per-site visualisation used to do to a browser.


def look_at(code, dfq=None, cif_directory=None, show_3d=False, max_views=4):
    """
    Everything Eir knows about one entry.

    code           ICSD collection code, or a filename, or part of one
    show_3d        draw the coordination polyhedra. Off by default; each
                   viewer is a live WebGL context and a browser holds few.
    max_views      hard cap on viewers for this call
    """
    _df = dfq if dfq is not None else globals().get("dfq")
    if _df is None:
        print("No results in memory. Run the post-processing cell first.")
        return None

    _key = str(code).strip()
    _m = _df[_df["icsd_code"].astype(str).str.strip() == _key]
    if not len(_m):
        _m = _df[_df["filename"].astype(str).str.contains(_key, case=False,
                                                          na=False)]
    if not len(_m):
        print(f"Nothing matching {_key!r}. Try an ICSD code or part of a "
              f"filename.")
        return None
    if _m["filename"].nunique() > 1:
        _n = _m["filename"].nunique()
        print(f"{_key!r} matches {_n} files. Be more specific:")
        for _f in sorted(_m["filename"].unique())[:8]:
            print(f"    {_f}")
        if _n > 8:
            print(f"    ... and {_n - 8} more")
        return None

    r0 = _m.iloc[0]
    _line = "=" * 78
    print(_line)
    print(f"  {r0['chemical_formula']}   ICSD {r0['icsd_code']}"
          f"   {r0.get('space_group', '?')}")
    print(f"  {r0.get('year', '?')}  {str(r0.get('journal', ''))[:52]}")
    if r0.get("authors") == r0.get("authors"):
        print(f"  {str(r0.get('authors'))[:70]}")
    print(_line)

    # ---- the verdict ---------------------------------------------------
    _tier = r0.get("structure_pgrm_tier")
    if _tier == _tier and _tier is not None:
        print(f"\n  VERDICT   {_tier}")
        if r0.get("structure_pgrm_reason") == r0.get("structure_pgrm_reason"):
            print(f"            {r0['structure_pgrm_reason']}")
        if r0.get("structure_pgrm_evidence") == r0.get("structure_pgrm_evidence"):
            print(f"            {r0['structure_pgrm_evidence']}")
        if _tier == "EXPUNGE":
            print("\n  Quote no bond valence result for this entry. The")
            print("  numbers below are computed from coordinates that")
            print("  cannot be right, and are shown so you can see why.")

    # ---- the screens ---------------------------------------------------
    print("\n  SCREENS")
    for _n, _c in (("radii ratio", "structure_core_geometry_plausible"),
                   ("bond-valence distance", "structure_bvs_geometry_plausible"),
                   ("anion-anion packing", "anion_packing_plausible"),
                   ("cation-cation packing", "cation_packing_plausible"),
                   ("coordination", "structure_cn_plausible")):
        if _c in r0.index:
            _v = str(r0[_c]).lower()
            _mark = "FAIL" if _v == "false" else ("pass" if _v == "true" else "--")
            print(f"    {_n:<24} {_mark}")
    for _n, _c in (("shortest anion-anion", "anion_anion_min"),
                   ("shortest cation-cation", "cation_cation_min")):
        if _c in r0.index and r0[_c] == r0[_c]:
            print(f"    {_n:<24} {r0[_c]:.3f} A")

    # ---- the sites -----------------------------------------------------
    print("\n  SITES")
    _cols = [c for c in ("site_label", "element", "valence", "occupancy", "cn",
                         "cn_gap_shell", "bvs", "bvs_percent_diff",
                         "bl_delta_mean", "bl_n_bonds", "min_bond_length",
                         "econ_cn_ratio", "geometry")
             if c in _m.columns]
    for _l in _m[_cols].to_string(index=False).splitlines():
        print("    " + _l)

    print()
    for _c, _lab in (("gii", "GII"), ("wagii", "WAGII"),
                     ("gii_site_averaged", "GII site-averaged"),
                     ("gii_recommended", "recommended")):
        if _c in r0.index and r0[_c] == r0[_c]:
            _v = r0[_c]
            _txt = f"{_v:.4f}" if isinstance(_v, float) else str(_v)
            print(f"    {_lab:<20} {_txt}")

    if r0.get("proposed_shift") == r0.get("proposed_shift") or (
            "shift_verdict" in r0.index and r0["shift_verdict"] == r0["shift_verdict"]):
        print("\n  PROPOSED SHIFT")
        for _c in ("proposed_shift", "shift_shell_spread", "proposed_spread",
                   "shift_verdict", "shift_evidence"):
            _s = _m[_c].dropna() if _c in _m.columns else []
            if len(_s):
                print(f"    {_c:<22} {_s.iloc[0]}")

    # ---- 3D, on request only -------------------------------------------
    if show_3d:
        if not globals().get("PY3DMOL_AVAILABLE", False):
            print("\n  [3D unavailable: py3Dmol is not installed]")
        elif cif_directory is None and "EIR_CIF_DIRECTORY" not in globals():
            print("\n  [3D needs the CIFs: pass cif_directory=...]")
        else:
            _dir = cif_directory or EIR_CIF_DIRECTORY
            _drawn = 0
            for _, _s in _m.iterrows():
                if _drawn >= max_views:
                    print(f"\n  [stopped at {max_views} viewers; raise "
                          f"max_views if you need more]")
                    break
                try:
                    visualize_problematic_site_3d(
                        os.path.join(_dir, _s["filename"]),
                        _s["element"], _s["site_label"], None,
                        _s.get("deviation"), _s.get("valence"),
                        _s.get("bvs"), filename=_s["filename"])
                    _drawn += 1
                except Exception as _e:
                    print(f"    [3D failed for {_s['site_label']}: "
                          f"{type(_e).__name__}: {_e}]")
    else:
        print("\n  Pass show_3d=True to draw the coordination polyhedra.")

    print()
    return _m
